package com.nextrade.service; import javax.crypto.SecretKey; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; public final class JwtKeyRing {private final Map<String,SecretKey> keys=new LinkedHashMap<>();private String activeKid;public JwtKeyRing(String activeKid,Map<String,String> secrets){for(var e:secrets.entrySet())keys.put(e.getKey(),new SecretKeySpec(Base64.getDecoder().decode(e.getValue()),"HmacSHA256"));if(!keys.containsKey(activeKid))throw new IllegalArgumentException("Active kid missing");this.activeKid=activeKid;}public synchronized String activeKid(){return activeKid;}public synchronized SecretKey active(){return keys.get(activeKid);}public synchronized SecretKey key(String kid){SecretKey k=keys.get(kid);if(k==null)throw new IllegalArgumentException("Unknown kid");return k;}public synchronized Set<String> kids(){return Set.copyOf(keys.keySet());}}
